('c0000000-0000-0000-0000-000000000001', 'Gupta Premium Ball Pen (Blue)', 'gupta-premium-ball-pen-blue', 'GS-PEN-01', 15, 20, 500, TRUE, FALSE, FALSE, 4.8, 1247, 'Smooth, continuous writing experience with refillable cartridge. Perfect for daily office and academic use.', 'The Gupta Premium Ball Pen is our signature bestselling writing instrument, trusted by thousands of students, teachers, and business professionals across Raipur since 1995. Crafted for effortless ink flow with zero leakage and ergonomic grip.', '["Smooth, continuous writing experience","2000+ words capacity per pen","Refillable cartridge (saves money & reduces plastic)","Durable break-resistant body","Perfect ergonomic grip for long writing sessions"]'::jsonb, '{"Tip Size":"1.0mm Swiss Carbide Tip","Ink Color":"Vibrant Blue","Ink Type":"Oil-based Low Viscosity Ink","Body Material":"High-Grade Impact Polymer","Length":"14 cm","Word Capacity":"2000+ words","Refillable":"Yes (Spare refills at ₹5 each)","Certification":"ISI Certified","Origin":"Made in India"}'::jsonb, '[{"minQty":1,"maxQty":9,"discountPercent":0,"pricePerUnit":15},{"minQty":10,"maxQty":49,"discountPercent":20,"pricePerUnit":12},{"minQty":50,"maxQty":99,"discountPercent":33,"pricePerUnit":10},{"minQty":100,"maxQty":499,"discountPercent":47,"pricePerUnit":8},{"minQty":500,"discountPercent":60,"pricePerUnit":6}]'::jsonb, '["https://images.unsplash.com/photo-1583485088034-697b5bc54ccd?q=80&w=900&auto=format&fit=crop","https://images.unsplash.com/photo-1585336261026-77cc7c97f266?q=80&w=900&auto=format&fit=crop","https://images.unsplash.com/photo-1569683795645-b62e50fbf103?q=80&w=900&auto=format&fit=crop"]'::jsonb, '[{"name":"Blue","hex":"#1e40af"},{"name":"Black","hex":"#111827"},{"name":"Red","hex":"#dc2626"}]'::jsonb),
('c0000000-0000-0000-0000-000000000001', 'Gupta Gel Pen Set (10 Colors)', 'gupta-gel-pen-set-10-colors', 'GS-GEL-10', 180, 220, 200, TRUE, FALSE, FALSE, 4.9, 892, 'Vibrant Japanese gel inks with ultra-fast drying technology. Ideal for notes, bullet journaling, and sketching.', 'Experience effortless artistic expression and crisp note-taking. Each pen features a 0.7mm fine roller tip and quick-drying, smudge-proof water-resistant Japanese gel ink formulation.', '["10 rich vibrant color spectrum","Quick-dry smudge-proof Japanese gel ink","0.7mm precision needle point","Cushioned rubberized comfort barrel"]'::jsonb, '{"Tip Size":"0.7mm Fine Needle Tip","Color Count":"10 Assorted Colors","Ink Type":"Waterproof Pigment Gel","Grip":"Contoured Soft Rubber Grip"}'::jsonb, '[{"minQty":1,"maxQty":9,"discountPercent":0,"pricePerUnit":180},{"minQty":10,"maxQty":49,"discountPercent":17,"pricePerUnit":150},{"minQty":50,"discountPercent":33,"pricePerUnit":120}]'::jsonb, '["https://images.unsplash.com/photo-1569683795645-b62e50fbf103?q=80&w=900&auto=format&fit=crop","https://images.unsplash.com/photo-1583485088034-697b5bc54ccd?q=80&w=900&auto=format&fit=crop"]'::jsonb, '[]'::jsonb),
